    @PostMapping(value = "/account/changeStatus", produces = MediaType.APPLICATION_JSON_VALUE)
    public GenericResponse<Void> changeStatus(@RequestBody MerchantChangeStatusDTO merchantChangeStatusDTO) {
        UserDTO userDTO = SecurityUtil.obtainUser();
        if (isNull(userDTO)) {
            throw new TokenException(LOGIN_EXPIRED);
