@Caching(evict = {
        @CacheEvict(value = CacheConstants.CACHE_NAME_ACCOUNT_AUTH, key = "#accountId+''"),
        @CacheEvict(value = CacheConstants.CACHE_NAME_ACCOUNT_AUTH_INFO, key = "#accountId+''"),
        @CacheEvict(value = CacheConstants.CACHE_NAME_ACCOUNT_AUTH_PERMISSION, key = "#accountId+''"),
})
@Transactional(rollbackFor = Exception.class)
public void updateStatus(Long accountId, Integer status, String modifier) {
    AuthAccountDO existAccount = authAccountDOMapper.selectByAccountId(accountId);
    if (existAccount == null){
        throw new BizException("账号不存在:"+ accountId);
    }

    AuthAccountDO authAccountDO = new AuthAccountDO();
    authAccountDO.setStatus(status);
    authAccountDO.setId(existAccount.getId());
    authAccountDO.setModifierName(modifier);
    int res = authAccountDOMapper.updateByPrimaryKeySelective(authAccountDO);
    if (res <= 0){
        throw new BizException("更新失败:"+ accountId);
    }
    // 启用 - 绑定外呼
    if (Objects.equals(status, AccountStatusEnum.NORMAL.getCode())){
        String phoneCallAccount = this.bindPhoneCallAccountFromPool(accountId.intValue());
        if (StringUtils.isEmpty(phoneCallAccount)){
            throw new BizException("无可用外呼账号，无法启用账号，请联系国泰管理员。");
        }
    }
    // 停用 - 解绑外呼
    if (Objects.equals(status, AccountStatusEnum.DISABLE.getCode())){
        this.unbindPhoneCallAccount(accountId.intValue());
    }

}


/**
 * 获取账号角色
 */
public List<AuthRoleE> getRoles(String accountId, boolean permission) {
    List<AuthRoleE> authRoleES = Lists.newArrayList();
    List<String> roleCodes = authAccountRoleDOMapper.getRoleCodes(Long.parseLong(accountId));
    if (CollectionUtils.isEmpty(roleCodes)) {
        return authRoleES;
    }
    List<AuthRoleDO> authRoleDOS = authRoleDOMapper.selectByRoleCodes(roleCodes);
    for (AuthRoleDO authRoleDO : authRoleDOS) {
        authRoleES.add(buildAuthRoleE(authRoleDO, permission));
    }
    return authRoleES;
}


